
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_n12_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_n12", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.034302604774737e-01, -1.021714550536860e-01, -1.004383234222274e-01, -9.812251204900256e-02, -9.519079097210018e-02, -9.182566729940157e-02, -8.853828774322095e-02, -8.548558995716317e-02, -7.875029917092337e-02, -5.701053270520673e-02, -2.858158809102650e-02, -4.861399271477339e-02, -5.336289677847759e-02, -4.103914041311513e-02, -2.558058473935578e-02, -2.764221982670099e-02, -7.382066270064587e-02, -3.370106778659449e-02, -6.313725295795287e-03, -6.915453348154600e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


